import { cacheLife, cacheTag } from 'next/cache'
import { getAllProducts } from '@/lib/db'

export interface Product {
  id: number
  name: string
  price: number
}

// Cached read for the product catalog. Every view that renders catalog data
// should go through this function so it shares the "products" cache tag and
// picks up invalidations from the sync action together.
export async function getProducts(): Promise<Product[]> {
  'use cache'
  cacheTag('products')
  // Catalog data only changes when an operator syncs or upstream pushes an
  // update, so keep it warm for a long time; on-demand invalidation via the
  // "products" tag handles freshness.
  cacheLife('hours')

  return getAllProducts()
}

