import { revalidateTag } from 'next/cache'
import { triggerCatalogSync } from '@/lib/db'
import { getProducts } from '@/lib/products'

export default async function AdminProductsPage() {
  async function syncCatalog() {
    'use server'

    // Kick off the upstream ERP/PIM sync job (pricing, inventory,
    // availability). It can touch thousands of SKUs, so we don't wait for it.
    await triggerCatalogSync()

    // Mark all "products"-tagged cache entries stale. Views keep serving the
    // existing catalog while fresh data is recomputed in the background
    // (stale-while-revalidate), so the admin can keep working immediately.
    // We deliberately avoid updateTag(), which would block this request on a
    // full recompute to guarantee read-your-writes.
    revalidateTag('products', 'max')
  }

  const products = await getProducts()

  return (
    <main>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

